CREATE OR REPLACE TRIGGER D_ACCOUNT_MAPPING_TRG
BEFORE INSERT OR UPDATE ON D_ACCOUNT_MAPPING FOR EACH ROW
DECLARE  vtmp number;  
BEGIN  
    IF INSERTING THEN  
        :NEW.UPD_DATE    := SYSDATE;  
        :NEW.UPD_USER    := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;  
    ELSIF UPDATING THEN  
        :NEW.UPD_DATE     := SYSDATE;  
        :NEW.UPD_USER     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;          
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE; 
END;
/


