    IF UPDATING THEN  
        :NEW.TOTAL    := NVL(:NEW.BUD_JAN,0)+NVL(:NEW.BUD_FEB,0)+NVL(:NEW.BUD_MAR,0)+NVL(:NEW.BUD_APR,0)+NVL(:NEW.BUD_MAY,0)+NVL(:NEW.BUD_JUN,0)
