CREATE OR REPLACE TRIGGER F_RESPONSIBILITY_ADV_HDR_TRG
    Before Insert Or Update
    ON F_RESPONSIBILITY_ADVANCE_HDR
    For Each Row
DISABLE
Declare
    Vtmp                  Number;
    Vnum                  Number;
    Vrepnum               Varchar2 (30);
    Vosl1                 Varchar2 (30);
    Vosl2                 Varchar2 (30);
    Vosl3                 Varchar2 (30);
    Vosl4                 Varchar2 (30);
    Vassets_Code          Varchar2 (50);
    Vrprass_Assets_Code   Varchar2 (50);
    Vsub2_Clsfa_Code      Varchar2 (50);
    Vassets_Name          Varchar2 (50);
    Vclsfa_Code           Varchar2 (50);
    Vsub1_Clsfa_Code      Varchar2 (50);
    Vasset_Merk_Code      Varchar2 (50);
    Vasset_Type           Varchar2 (50);
    Vasscond_Code         Varchar2 (50);
    Vasset_Serial_Number  Varchar2 (50);
    Vacquisition_Value Number;
    Vdate_Apr Date;
    Vpv_Num Varchar2 (50);
    V_INIT_CLSFA_NAME       VARCHAR2(50);
Begin
    If Updating
    Then
        If :Old.Status_Aprcd = 'Y'
        Then
            Begin
                Select Rprass_Num,
                       Osl1,
                       Osl2,
                       Osl3,
                       Osl4,
                       Pv_Num
                  Into Vrepnum,
                       Vosl1,
                       Vosl2,
                       Vosl3,
                       Vosl4,
                       Vpv_Num
                  From Git_Acc.F_Payment_Voucher_Hdr H
                 Where Pv_Num = :Old.Pv_Num;
            Exception
                When Others
                Then
                    Vrepnum := Null;
                    Vosl1 := Null;
                    Vosl2 := Null;
                    Vosl3 := Null;
                    Vosl4 := Null;
            End;

            Select Count (1)
              Into Vnum
              From Git_Invis.F_Repair_Assets
             Where Rprass_Num = Vrepnum;

            If Vnum >= 1
            Then
            
            Begin
            Select Nvl(Sum(D.Rad_Amount),0) Into Vacquisition_Value 
            From Git_Acc.F_Responsibility_Advance_Dtl D
            Where D.Rad_Num = :New.Rad_Num; --AND H.PV_NUM = VPV_NUM;
            Exception
                When Others
                Then Vacquisition_Value := Null;
            End;

            Begin
            Select H.Date_Apr Into Vdate_Apr From Git_Acc.F_Responsibility_Advance_Hdr H
            Where H.Rad_Num = :New.Rad_Num;
            Exception
                When Others
                Then Vdate_Apr := Null;
            End;
            
                Begin
                    Select Rprass_Assets_Code
                      Into Vrprass_Assets_Code
                      From Git_Invis.F_Repair_Assets
                     Where Rprass_Num = Vrepnum;
                Exception
                    When Others
                    Then
                        Vrprass_Assets_Code := Null;
                End;

                Begin
                    Select Assets_Name,
                           Clsfa_Code,
                           Sub1_Clsfa_Code,
                           Sub2_Clsfa_Code,
                           Asset_Merk_Code,
                           Asset_Type,
                           Asscond_Code,
                           Asset_Serial_Number
                      Into Vassets_Name,
                           Vclsfa_Code,
                           Vsub1_Clsfa_Code,
                           Vsub2_Clsfa_Code,
                           Vasset_Merk_Code,
                           Vasset_Type,
                           Vasscond_Code,
                           Vasset_Serial_Number
                      From Git_Invis.D_Assets
                     Where Assets_Code = Vrprass_Assets_Code;
                Exception
                    When Others
                    Then
                        Vsub2_Clsfa_Code := Null;
                End;

                SELECT INIT_CLSFA_NAME
                INTO V_INIT_CLSFA_NAME
                FROM GIT_INVIS.D_CLASSIFICATION_FA
                WHERE CLSFA_CODE = Vclsfa_Code;
                
                GIT_INVIS.AUTONUM_GIT('FA'||Vosl1||NULL||NULL||NULL,V_INIT_CLSFA_NAME,
                          To_Char (Sysdate, 'YYYY'),TO_CHAR(SYSDATE,'MM'),TO_CHAR(SYSDATE,'DD'),
                          Vosl1,NULL,NULL,NULL,Vassets_Code);
                         
                Insert Into Git_Invis.D_Assets (Assets_Code,
                                                Assets_Name,
                                                Clsfa_Code,
                                                Sub1_Clsfa_Code,
                                                Sub2_Clsfa_Code,
                                                Asset_Merk_Code,
                                                Asset_Type,
                                                Asset_Serial_Number,
                                                Asscond_Code,
                                                Acquisition_Date,
                                                Acquisition_Value,
                                                Osl1,
                                                Osl2,
                                                Osl3,
                                                Osl4,
                                                Assets_Code_From)
                     Values (Vassets_Code,
                             Vassets_Name,
                             Vclsfa_Code,
                             Vsub1_Clsfa_Code,
                             Vsub2_Clsfa_Code,
                             Vasset_Merk_Code,
                             Vasset_Type,
                             Vasset_Serial_Number,
                             Vasscond_Code,
                             :New.Date_Apr,
                             Nvl(Vacquisition_Value,0),
                             Vosl1,
                             Vosl2,
                             Vosl3,
                             Vosl4,
                             Vrprass_Assets_Code);
                             
 Git_Invis.P_Depreciation_Process(Vassets_Code);
                        begin
                            update Git_Invis.F_Repair_Assets
                            set RPRASS_ASSETS_CODE_NEW = Vassets_Code
                            Where Rprass_Num = Vrepnum;
                        end;
                        
            End If;
        End If;
    End If;
Exception
    When Others
    Then
        Raise;
End;
/


CREATE OR REPLACE TRIGGER GT_MST_JOURNAL_ADJUSTMENT_TRG
BEFORE INSERT OR UPDATE ON GT_MST_JOURNAL_ADJUSTMENT FOR EACH ROW
DECLARE  vtmp number;  
BEGIN  
    IF INSERTING THEN  
        NULL;
    ELSIF UPDATING THEN  
        IF :OLD.CURR_CODE <> :NEW.CURR_CODE THEN
            UPDATE GIT_ACC_FISKAL.GT_DTL_JOURNAL_ADJUSTMENT
            SET CURRENCY_CODE   = :NEW.CURR_CODE,
                VALUE_DB        = (VALUE_INT_DB  * :NEW.CURR_RATE),
                VALUE_CR        = (VALUE_INT_CR  * :NEW.CURR_RATE),
                RATE            = :NEW.CURR_RATE
            WHERE NUM_OF_JOURNAL_ADJUSTMENT = :NEW.APP_SESSION;
        END IF;  
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE;
END;
/


