CREATE OR REPLACE TRIGGER JOURNAL_ADJ_AFTER_INSERT
AFTER INSERT ON DTL_JOURNAL_ADJUSTMENT FOR EACH ROW
DECLARE
  DS_TRX    VARCHAR2(300);
  DT_ENT DATE;
  DT_TRX DATE;
  USR_ENT  VARCHAR2(100);
  TGL_JT  DATE;
  NDP VARCHAR2(35);
  V_SEQ_NO NUMBER;
  V_CEK_JA NUMBER;
  V_PC_CODE         VARCHAR2(10); 
  V_KP_CODE         VARCHAR2(10);
  V_BAGIAN_CODE     VARCHAR2(10);
  V_SECTION_CODE    VARCHAR2(10);
BEGIN

    SELECT DESC_TRX, DATE_OF_ENTRY, USER_ENTRY,DATE_SETTLEMENT,NUM_DP, DATE_OF_TRX,SEQ_NO, PC_CODE, KP_CODE, BAGIAN_CODE, SECTION_CODE
    INTO DS_TRX, DT_ENT, USR_ENT,TGL_JT,NDP, DT_TRX,V_SEQ_NO, V_PC_CODE, V_KP_CODE, V_BAGIAN_CODE, V_SECTION_CODE
    FROM MST_JOURNAL_ADJUSTMENT
    WHERE NUM_OF_JOURNAL_ADJUSTMENT = :NEW.NUM_OF_JOURNAL_ADJUSTMENT;

    INSERT INTO JOURNAL
    (NUM_OF_TRX, DATE_OF_TRX, DESC_OF_TRANS, ACCOUNT, VALUE_DB,
    VALUE_CR, VALUE_INT_DB, VALUE_INT_CR, DATE_OF_ENTRY, USER_ENTRY,
    PC_CODE, KP_CODE, CODE_BAGIAN,SECTION_CODE,DUE_DATE,NUM_DP, SEQ_NO, SLA_CODE,SLA_NAME,CURRENCY_CODE,RATE)
    VALUES
    (:NEW.NUM_OF_JOURNAL_ADJUSTMENT, DT_TRX, DECODE(:NEW.DESCRIPTION, NULL, DS_TRX, :NEW.DESCRIPTION), :NEW.ACCOUNT,
    :NEW.VALUE_DB, :NEW.VALUE_CR, :NEW.VALUE_INT_DB, :NEW.VALUE_INT_CR, DT_ENT, USR_ENT,
    V_PC_CODE, V_KP_CODE, V_BAGIAN_CODE, V_SECTION_CODE, TGL_JT,NDP, V_SEQ_NO, :NEW.SLA_CODE, :NEW.SLA_NAME, :NEW.CURRENCY_CODE, :NEW.RATE);


END;
/


CREATE OR REPLACE TRIGGER JOURNAL_AFTER_INSERT
AFTER INSERT ON JOURNAL FOR EACH ROW
DECLARE
  BAL_DB VARCHAR2(1);
  BAL_CR VARCHAR2(1);
  RL_DB  VARCHAR2(1);
  RL_CR  VARCHAR2(1);
  BAL VARCHAR2(1);
  RL  VARCHAR2(1);

BEGIN

    SELECT NVL(BALANCE_DB,'N'), NVL(BALANCE_CR,'N'), NVL(PL_DB,'N'), NVL(PL_CR,'N')
    INTO   BAL_DB, BAL_CR, RL_DB, RL_CR
    FROM MST_COA
    WHERE ACCOUNT  = :NEW.ACCOUNT;
    --AND PC_CODE = :NEW.PC_CODE;
    
    IF BAL_DB = 'Y' OR BAL_CR = 'Y' THEN
       BAL := 'Y';
    ELSE
       BAL := 'N';
    END IF;
    IF RL_DB = 'Y' OR RL_CR = 'Y' THEN
       RL := 'Y';
    ELSE
       RL := 'N';
    END IF;
    
    
    ---------------------------------
    ---   FOR TABLE TRIAL BALANCE ---
    ----------------------------------
    IF SUBSTR(:NEW.NUM_OF_TRX,1,2) = 'JA' THEN
----
         IF :NEW.PC_CODE IS NULL AND :NEW.KP_CODE  IS NULL AND :NEW.CODE_BAGIAN IS NULL AND :NEW.SECTION_CODE IS NULL THEN
            UPDATE TRIAL_BALANCE SET
                ADJUSTMENT_DB = NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0),
                ADJUSTMENT_CR = NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0),
                BALANCING_DB = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                BALANCING_CR = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_CR,0)  + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL),
                INCOME_STATMENT_DB = DECODE(RL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                INCOME_STATMENT_CR = DECODE(RL,'Y', NVL(BEGIN_BALANCE_CR,0) + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL)
            WHERE
                PC_CODE  IS NULL AND
                KP_CODE  IS NULL AND
                BAGIAN_CODE  IS NULL AND
                SECTION_CODE IS NULL AND
                ACCOUNT  = :NEW.ACCOUNT AND
                TB_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM')) AND
                TB_YEAR     = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'));
         ELSIF :NEW.PC_CODE IS NOT NULL AND :NEW.KP_CODE  IS NULL AND :NEW.CODE_BAGIAN IS NULL AND :NEW.SECTION_CODE IS NULL THEN
            UPDATE TRIAL_BALANCE SET
                ADJUSTMENT_DB = NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0),
                ADJUSTMENT_CR = NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0),
                BALANCING_DB = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                BALANCING_CR = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_CR,0)  + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL),
                INCOME_STATMENT_DB = DECODE(RL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                INCOME_STATMENT_CR = DECODE(RL,'Y', NVL(BEGIN_BALANCE_CR,0) + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL)
            WHERE
                PC_CODE  = :NEW.PC_CODE AND
                KP_CODE  IS NULL AND
                BAGIAN_CODE  IS NULL AND
                SECTION_CODE IS NULL AND
                 ACCOUNT  = :NEW.ACCOUNT AND
                TB_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM')) AND
                TB_YEAR     = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'));
         ELSIF :NEW.PC_CODE IS NOT NULL AND :NEW.KP_CODE  IS NOT NULL AND :NEW.CODE_BAGIAN IS NULL AND :NEW.SECTION_CODE IS NULL THEN
            UPDATE TRIAL_BALANCE SET
                ADJUSTMENT_DB = NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0),
                ADJUSTMENT_CR = NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0),
                BALANCING_DB = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                BALANCING_CR = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_CR,0)  + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL),
                INCOME_STATMENT_DB = DECODE(RL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                INCOME_STATMENT_CR = DECODE(RL,'Y', NVL(BEGIN_BALANCE_CR,0) + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL)
            WHERE
                PC_CODE  = :NEW.PC_CODE AND
                KP_CODE  = :NEW.KP_CODE AND
                BAGIAN_CODE  IS NULL AND
                SECTION_CODE IS NULL AND
                 ACCOUNT  = :NEW.ACCOUNT AND
                TB_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM')) AND
                TB_YEAR     = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'));
         ELSIF :NEW.PC_CODE IS NOT NULL AND :NEW.KP_CODE  IS NOT NULL AND :NEW.CODE_BAGIAN IS  NOT NULL AND :NEW.SECTION_CODE IS NULL THEN
            UPDATE TRIAL_BALANCE SET
                ADJUSTMENT_DB = NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0),
                ADJUSTMENT_CR = NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0),
                BALANCING_DB = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                BALANCING_CR = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_CR,0)  + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL),
                INCOME_STATMENT_DB = DECODE(RL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                INCOME_STATMENT_CR = DECODE(RL,'Y', NVL(BEGIN_BALANCE_CR,0) + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL)
            WHERE
                PC_CODE  = :NEW.PC_CODE AND
                KP_CODE  = :NEW.KP_CODE AND
                BAGIAN_CODE  = :NEW.CODE_BAGIAN AND
                SECTION_CODE IS NULL AND
                 ACCOUNT  = :NEW.ACCOUNT AND
                TB_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM')) AND
                TB_YEAR     = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'));
         ELSIF :NEW.PC_CODE IS NOT NULL AND :NEW.KP_CODE  IS NOT NULL AND :NEW.CODE_BAGIAN IS  NOT NULL AND :NEW.SECTION_CODE IS NOT NULL THEN
            UPDATE TRIAL_BALANCE SET
                ADJUSTMENT_DB = NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0),
                ADJUSTMENT_CR = NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0),
                BALANCING_DB = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                BALANCING_CR = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_CR,0)  + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL),
                INCOME_STATMENT_DB = DECODE(RL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                INCOME_STATMENT_CR = DECODE(RL,'Y', NVL(BEGIN_BALANCE_CR,0) + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL)
            WHERE
                PC_CODE  = :NEW.PC_CODE AND
                KP_CODE  = :NEW.KP_CODE AND
                BAGIAN_CODE  = :NEW.CODE_BAGIAN AND
                SECTION_CODE = :NEW.SECTION_CODE AND
                 ACCOUNT  = :NEW.ACCOUNT AND
                TB_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM')) AND
                TB_YEAR     = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'));
         END IF;

        IF SQL%NOTFOUND THEN
           INSERT INTO TRIAL_BALANCE
           (ACCOUNT, ADJUSTMENT_DB, ADJUSTMENT_CR,
