                TB_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM')) AND
                TB_YEAR     = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'));
         ELSIF :NEW.PC_CODE IS NOT NULL AND :NEW.KP_CODE  IS NOT NULL AND :NEW.CODE_BAGIAN IS  NOT NULL AND :NEW.SECTION_CODE IS NOT NULL THEN
            UPDATE TRIAL_BALANCE_SLA SET
                BEGIN_BALANCE_DB = NVL(BEGIN_BALANCE_DB,0) + NVL(:NEW.VALUE_DB,0),
                BEGIN_BALANCE_CR = NVL(BEGIN_BALANCE_CR,0) + NVL(:NEW.VALUE_CR,0),
                BALANCING_DB = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                BALANCING_CR = DECODE(BAL,'Y', NVL(BEGIN_BALANCE_CR,0) + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL),
                INCOME_STATMENT_DB = DECODE(RL,'Y', NVL(BEGIN_BALANCE_DB,0) + NVL(ADJUSTMENT_DB,0) + NVL(:NEW.VALUE_DB,0), NULL),
                INCOME_STATMENT_CR = DECODE(RL,'Y', NVL(BEGIN_BALANCE_CR,0) + NVL(ADJUSTMENT_CR,0) + NVL(:NEW.VALUE_CR,0), NULL)
            WHERE
                PC_CODE  = :NEW.PC_CODE AND
                KP_CODE  = :NEW.KP_CODE AND
                BAGIAN_CODE  = :NEW.CODE_BAGIAN AND
                SECTION_CODE = :NEW.SECTION_CODE AND
                ACCOUNT  = :NEW.ACCOUNT AND
                SLA_CODE = :NEW.SLA_CODE AND
                SLA_NAME = :NEW.SLA_NAME AND
                TB_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM')) AND
                TB_YEAR     = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'));                
         END IF;


        IF SQL%NOTFOUND THEN
            IF :NEW.SLA_CODE IS NOT NULL THEN 
               INSERT INTO TRIAL_BALANCE_SLA
               (ACCOUNT, SLA_CODE, SLA_NAME, BEGIN_BALANCE_DB, BEGIN_BALANCE_CR,
                BALANCING_DB,BALANCING_CR,
                INCOME_STATMENT_DB, INCOME_STATMENT_CR,
                TB_MONTH, TB_YEAR, TB_YEAR_MONTH, PC_CODE, KP_CODE, BAGIAN_CODE, SECTION_CODE)
               VALUES
               (:NEW.ACCOUNT, :NEW.SLA_CODE, :NEW.SLA_NAME, NVL(:NEW.VALUE_DB,0), NVL(:NEW.VALUE_CR,0),
                DECODE(BAL,'Y', NVL(:NEW.VALUE_DB,0), NULL),
                DECODE(BAL,'Y', NVL(:NEW.VALUE_CR,0), NULL),
                DECODE(RL,'Y', NVL(:NEW.VALUE_DB,0), NULL),
                DECODE(RL,'Y', NVL(:NEW.VALUE_CR,0), NULL),
                TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM')),
                TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY')),
                TO_CHAR(:NEW.DATE_OF_TRX,'YYYYMM'),
                :NEW.PC_CODE, :NEW.KP_CODE, :NEW.CODE_BAGIAN, :NEW.SECTION_CODE);            
            END IF;
         END IF;
    END IF;   
    
END;
/


