DROP SEQUENCE SEQ_NO_JOURNAL;

CREATE SEQUENCE SEQ_NO_JOURNAL
  START WITH 543999
  MAXVALUE 9999999999999999999999999999
  MINVALUE 1
  NOCYCLE
  NOCACHE
  NOORDER
  NOKEEP
  NOSCALE
  GLOBAL;


CREATE OR REPLACE TRIGGER JOURNAL_MST_ADJ_AFTER_INSERT
BEFORE INSERT ON MST_JOURNAL_ADJUSTMENT FOR EACH ROW
DECLARE
  vtmp number;
V_CEK NUMBER;
BEGIN

    BEGIN
        SELECT COUNT(1)
        INTO V_CEK
        FROM GIT_ERP.D_CLOSING_ACCOUNTING
        WHERE CA_YEAR = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'))
        AND CA_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM'))
        AND OSL1 = :NEW.PC_CODE;
    END;
    
    IF INSERTING THEN  
        IF V_CEK > 0 THEN
            raise_application_error(-20001,'THE MONTH PERIOD ' || TO_CHAR(:NEW.DATE_OF_TRX,'MONTH') || ' ' || TO_CHAR(:NEW.DATE_OF_TRX,'YYYY') || ' IS ALREADY CLOSE, PLEASE CHANGE THE TRANSACTION DATE OR CONTACT ACCOUNTING');
        ELSE
           :NEW.SEQ_NO := GIT_ACC_FISKAL.SEQ_NO_JOURNAL.NEXTVAL; 
        END IF;  
   
    END IF;  
   
   /* NO LINK
    INSERT INTO MST_JOURNAL_ADJUSTMENT@LINK_TO_ACC_C
    (NUM_OF_JOURNAL_ADJUSTMENT, DESC_TRX, USER_ENTRY, DATE_OF_ENTRY, DATE_SETTLEMENT, NUM_DP, DATE_OF_TRX)
    VALUES
    (:NEW.NUM_OF_JOURNAL_ADJUSTMENT, :NEW.DESC_TRX, :NEW.USER_ENTRY, :NEW.DATE_OF_ENTRY, :NEW.DATE_SETTLEMENT, :NEW.NUM_DP, :NEW.DATE_OF_TRX);
   */
END;
/


CREATE OR REPLACE TRIGGER JOURNAL_MST_ADJ_AFTER_UPDATE
AFTER UPDATE
ON MST_JOURNAL_ADJUSTMENT 
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
BEGIN

    -- UPDATE ONLY COLUMN DESC_TRX

    UPDATE JOURNAL
    SET DESC_OF_TRANS = :NEW.DESC_TRX
    WHERE NUM_OF_TRX = :NEW.NUM_OF_JOURNAL_ADJUSTMENT;
   /*
    UPDATE JOURNAL@LINK_TO_ACC_C
    SET DESC_OF_TRANS = :NEW.DESC_TRX
    WHERE NUM_OF_TRX = :NEW.NUM_OF_JOURNAL_ADJUSTMENT;
     */
END;
/


CREATE OR REPLACE TRIGGER JOURNAL_MST_MEMO_AFTER_INSERT
BEFORE INSERT ON MST_TRX_JOURNAL_MEMO FOR EACH ROW
DECLARE
  vtmp number;
V_CEK NUMBER;
BEGIN

    BEGIN
        SELECT COUNT(1)
        INTO V_CEK
        FROM GIT_ERP.D_CLOSING_ACCOUNTING
        WHERE CA_YEAR = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'YYYY'))
        AND CA_MONTH = TO_NUMBER(TO_CHAR(:NEW.DATE_OF_TRX,'MM'))
        AND OSL1 = :NEW.PC_CODE;
    END;
    
    IF INSERTING THEN  
        IF V_CEK > 0 THEN
            raise_application_error(-20001,'THE MONTH PERIOD ' || TO_CHAR(:NEW.DATE_OF_TRX,'MONTH') || ' ' || TO_CHAR(:NEW.DATE_OF_TRX,'YYYY') || ' IS ALREADY CLOSE, PLEASE CHANGE THE TRANSACTION DATE OR CONTACT ACCOUNTING');
        ELSE
           :NEW.SEQ_NO := GIT_ACC_FISKAL.SEQ_NO_JOURNAL.NEXTVAL;  
        END IF;  
   
    END IF;  
     
    /*  NO LINK --
    INSERT INTO MST_TRX_JOURNAL_MEMO@LINK_TO_ACC_C
    (NUM_OF_TRX_JOURNAL_MEMO, DATE_OF_TRX, DESC_TRX, USER_ENTRY, DATE_OF_ENTRY)
    VALUES
    (:NEW.NUM_OF_TRX_JOURNAL_MEMO, :NEW.DATE_OF_TRX, :NEW.DESC_TRX, :NEW.USER_ENTRY, :NEW.DATE_OF_ENTRY);
    */
END;
/


CREATE OR REPLACE TRIGGER JOURNAL_MST_MEMO_AFTER_UPDATE
AFTER UPDATE ON MST_TRX_JOURNAL_MEMO
FOR EACH ROW
BEGIN

    -- UPDATE ONLY COLUMN DESC_TRX

	UPDATE JOURNAL
	SET DESC_OF_TRANS = :NEW.DESC_TRX
