  GLOBAL;


CREATE OR REPLACE TRIGGER MST_COA_TRG
BEFORE INSERT OR UPDATE ON MST_COA FOR EACH ROW
DECLARE  vtmp number;  
    vBALANCE_DB     varchar2(10);
    vBALANCE_CR     varchar2(10);
    vPL_DB          varchar2(10);
    vPL_CR          varchar2(10);
    vLEVEL_ACCOUNT  number(2);
    VPARENT_ACCOUNT varchar2(30); 
    VPC_CODE       varchar2(10);
BEGIN  
    IF INSERTING THEN  
        :NEW.SEQNUM         := GIT_ACC_FISKAL.SEQ_MST_COA.NEXTVAL;
        :NEW.DATE_CREATE    := SYSDATE;  
        :NEW.USER_CREATE    := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;
        :NEW.ST_ACTIVE      := 'Y';  
        ---GIT_ACC_FISKAL.PROC_CHANGE_PARENT_ACCOUNT (:NEW.PARENT_ACCOUNT, :NEW.PC_CODE, :NEW.BALANCE_DB, :NEW.BALANCE_CR, :NEW.PL_DB, :NEW.PL_CR, :NEW.LEVEL_ACCOUNT);
    ELSIF UPDATING THEN  
        :NEW.DATE_UPDATE     := SYSDATE;  
        :NEW.USER_UPDATE     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;    
      /*
        if nvl(:NEW.PARENT_ACCOUNT,'x') <>  nvl(:OLD.PARENT_ACCOUNT,'x') then
            
            VPARENT_ACCOUNT := :NEW.PARENT_ACCOUNT;
            VPC_CODE        := :NEW.PC_CODE;
            GIT_ACC_FISKAL.PROC_CHANGE_PARENT_ACCOUNT (VPARENT_ACCOUNT, VPC_CODE, vBALANCE_DB, vBALANCE_CR, vPL_DB, vPL_CR, vLEVEL_ACCOUNT); 
            
            :NEW.BALANCE_DB     := vBALANCE_DB;
            :NEW.BALANCE_CR     := vBALANCE_CR;
            :NEW.PL_DB          := vPL_DB;
            :NEW.PL_CR          := vPL_CR;
            :NEW.LEVEL_ACCOUNT  := vLEVEL_ACCOUNT;
        END IF;
       */ 
    END IF;  
END;
/


