CREATE OR REPLACE TRIGGER TMP_F_BUDGETING_TRG
BEFORE INSERT OR UPDATE ON TMP_F_BUDGETING_HDR FOR EACH ROW
DECLARE  vtmp number;  
BEGIN  
    IF INSERTING THEN  
       :NEW.ENT_DATE    := SYSDATE;  
        :NEW.ENT_USER    := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;  
    ELSIF UPDATING THEN  
        :NEW.UPD_DATE     := SYSDATE;  
        :NEW.UPD_USER     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;          
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE; 
END;
/


CREATE OR REPLACE TRIGGER TMP_F_GROUP_CASH_BANK_OUT_HDR_TRG
BEFORE INSERT OR UPDATE ON TMP_F_GROUP_CASH_BANK_OUT_HDR FOR EACH ROW
DECLARE  

BEGIN  
    IF INSERTING THEN  
        :NEW.DTCRE    := SYSDATE;  
        :NEW.USRCRE    := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;  
    ELSIF UPDATING THEN  
        :NEW.DTUPD     := SYSDATE;  
        :NEW.USRUPD     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;          
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE; 
END;
/


CREATE OR REPLACE TRIGGER TMP_F_OTHERS_INCOME_HDR_TRG
BEFORE INSERT OR UPDATE ON TMP_F_OTHERS_INCOME_HDR FOR EACH ROW
DECLARE  vtmp number;  
BEGIN  
    IF INSERTING THEN  
        NULL;
    ELSIF UPDATING THEN  
        IF :OLD.CURR_CODE <> :NEW.CURR_CODE THEN
            UPDATE GIT_ACC_FISKAL.TMP_F_OTHERS_INCOME_DTL
            SET OI_AMOUNT       = (OI_AMOUNT_CURR * :NEW.CURR_RATES)
            WHERE OI_NUM        = :NEW.OI_NUM;
        END IF;  
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE;
END;
/


CREATE OR REPLACE TRIGGER TMP_F_PAYMENT_VOUCHER_DTL_WHT_TRG
BEFORE INSERT OR UPDATE ON TMP_F_PAYMENT_VOUCHER_DTL_WHT FOR EACH ROW
DECLARE  V_RATES number;  
BEGIN  

    SELECT CURR_RATES INTO V_RATES
    FROM GIT_ACC_FISKAL.TMP_F_PAYMENT_VOUCHER_HDR
    WHERE PV_NUM = :NEW.PV_NUM;

    IF INSERTING THEN  
        :NEW.DTCRE    := SYSDATE;  
        :NEW.USRCRE   := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;  
        :NEW.AMOUNT   := :NEW.AMOUNT_CURR * V_RATES;
    ELSIF UPDATING THEN    
        :NEW.DTUPD     := SYSDATE;  
        :NEW.USRUPD    := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;
        :NEW.AMOUNT   := :NEW.AMOUNT_CURR * V_RATES;          
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE; 
END;
/


CREATE OR REPLACE TRIGGER TMP_F_PAYMENT_VOUCHER_HDR_TRG
BEFORE INSERT OR UPDATE ON TMP_F_PAYMENT_VOUCHER_HDR FOR EACH ROW
DECLARE  vtmp number;  
BEGIN  
    IF INSERTING THEN  
        NULL;
    ELSIF UPDATING THEN  
        IF :OLD.CURR_CODE <> :NEW.CURR_CODE THEN
            UPDATE GIT_ACC_FISKAL.TMP_F_PAYMENT_VOUCHER_DTL
            SET AMOUNT          = (AMOUNT_CURR  * :NEW.CURR_RATES)
            WHERE PV_NUM        = :NEW.PV_NUM;
        END IF;  
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE;
END;
/


