CREATE OR REPLACE TRIGGER BIU_EBA_DEMO_CHART_ORDERS
   before insert or update ON EBA_DEMO_CHART_ORDERS
   for each row
begin  
   if :new."ORDER_ID" is null then
     select to_number(sys_guid(),'XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX') into :new.order_id from dual;
   end if;
   if inserting then
       :new.created := localtimestamp;
       :new.created_by := nvl(wwv_flow.g_user,user);
       :new.updated := localtimestamp;
       :new.updated_by := nvl(wwv_flow.g_user,user);
   end if;
   if inserting or updating then
       :new.updated := localtimestamp;
       :new.updated_by := nvl(wwv_flow.g_user,user);
   end if;
end;
/


CREATE OR REPLACE TRIGGER DEMO_ORDER_ITEMS_AIUD_TOTAL
  after insert or update or delete ON DEMO_ORDER_ITEMS
begin
  -- Update the Order Total when any order item is changed
  update demo_orders set order_total =
  (select sum(unit_price*quantity) from demo_order_items
    where demo_order_items.order_id = demo_orders.order_id);
end;
/


CREATE OR REPLACE TRIGGER DEMO_ORDER_ITEMS_BI
  BEFORE insert ON DEMO_ORDER_ITEMS for each row
declare
  order_item_id number;
begin
  if :new.order_item_id is null then
    select demo_order_items_seq.nextval 
      into order_item_id 
      from dual;
    :new.order_item_id := order_item_id;
  end if;
end;
/


CREATE OR REPLACE TRIGGER DEMO_ORDER_ITEMS_BIU_GET_PRICE
  before insert or update ON DEMO_ORDER_ITEMS for each row
declare
  l_list_price number;
begin
  if :new.unit_price is null then
    -- First, we need to get the current list price of the order line item
    select list_price
    into l_list_price
    from demo_product_info
    where product_id = :new.product_id;
    -- Once we have the correct price, we will update the order line with the correct price
    :new.unit_price := l_list_price;
  end if;
end;
/


CREATE OR REPLACE TRIGGER D_CASHFLOW_SUBCATEGORY_TRG
BEFORE INSERT OR UPDATE ON D_CASHFLOW_SUBCATEGORY FOR EACH ROW
BEGIN  
    IF INSERTING THEN  
        :NEW.USRCRE     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;
        :NEW.DTCRE       := SYSDATE; 
    ELSIF UPDATING THEN  
        :NEW.USRUPD     := SYSDATE;  
        :NEW.DTCRE     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;          
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE; 
END;
/


CREATE OR REPLACE TRIGGER D_CASH_BANK_TRG
BEFORE INSERT OR UPDATE ON D_CASH_BANK FOR EACH ROW
DECLARE  
    V_ANUM  VARCHAR2(30);
BEGIN  
    IF INSERTING THEN  
        GIT_ACC_FISKAL.AUTONUM_GIT('CB'||:NEW.OSL1||:NEW.OSL2||:NEW.OSL3||:NEW.OSL4,:NEW.CBTYP,
                  TO_CHAR(SYSDATE,'YYYY'),TO_CHAR(SYSDATE,'MM'),TO_CHAR(SYSDATE,'DD'),
                  :NEW.OSL1,:NEW.OSL2,:NEW.OSL3,:NEW.OSL4,V_ANUM);
        :NEW.CBCD        := V_ANUM;
        :NEW.SEQNUM      := SEQ_D_CASH_BANK.NEXTVAL;
        :NEW.ENTUSR      := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;
        :NEW.DTUSR       := SYSDATE; 
    ELSIF UPDATING THEN  
        :NEW.UPD_DATE     := SYSDATE;  
        :NEW.UPD_USER     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;          
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE; 
END;
/


