CREATE OR REPLACE TRIGGER D_EXPEND_TRG
BEFORE INSERT OR UPDATE ON D_EXPEND FOR EACH ROW
DECLARE  vtmp number;  
VINIT VARCHAR2(5);
LNO NUMBER:=0;
BEGIN  
    BEGIN 
        SELECT NAMA_SINGKAT INTO VINIT
        FROM GIT_ERP.MST_PC
        WHERE PC_CODE= :NEW.OSL1;
    EXCEPTION
    WHEN OTHERS THEN
       VINIT:= 'GEN';
    END;
    
    LNO:=0;
    
    BEGIN  
        SELECT NVL(MAX(SUBSTR(EXPCD,-3,3)),0) INTO LNO
        FROM GIT_ACC_FISKAL.D_EXPEND
        WHERE OSL1 = :NEW.OSL1;
        LNO := LNO +1;
    EXCEPTION
    WHEN OTHERS THEN
       LNO:= 1;
    END;
        
    IF INSERTING THEN  
        :NEW.SEQNUM      := SEQ_D_EXPEND.NEXTVAL;
        :NEW.EXPCD       := 'TCB'||VINIT||LPAD(LNO,3,'0');   ----SEQ_D_EXPEND.NEXTVAL;
        --:NEW.EXPCD       := 'TCB'||VINIT||:NEW.EXPCD;
        :NEW.UPD_DATE    := SYSDATE;  
        :NEW.UPD_USER    := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;  
    ELSIF UPDATING THEN  
        :NEW.UPD_DATE     := SYSDATE;  
        :NEW.UPD_USER     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;          
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE; 
END;
/


CREATE OR REPLACE TRIGGER F_OTHERS_INCOME_HDR_TRG
BEFORE INSERT OR UPDATE
ON F_OTHERS_INCOME_HDR
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
DECLARE  vtmp number;  
BEGIN  
    IF INSERTING THEN  
        :NEW.DTUSR    := SYSDATE;  
        :NEW.ENTUSR    := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;  
    ELSIF UPDATING THEN  
        :NEW.UPD_DATE     := SYSDATE;  
        :NEW.UPD_USER     := CASE WHEN  v('APP_USER') IS  NULL THEN SYS_CONTEXT ('USERENV', 'TERMINAL') ELSE  v('APP_USER')  END;
        
        IF :OLD.CURR_CODE <> :NEW.CURR_CODE THEN
            UPDATE GIT_ACC_FISKAL.F_OTHERS_INCOME_DTL
            SET OI_AMOUNT       = (OI_AMOUNT_CURR * :NEW.CURR_RATES)
            WHERE OI_NUM        = :NEW.OI_NUM;
        END IF;  
                  
    END IF;  
EXCEPTION  
  WHEN OTHERS THEN RAISE; 
END;
/


