CREATE OR REPLACE TRIGGER JOURNAL_MEMO_AFTER_INSERT
AFTER INSERT ON DTL_TRX_JOURNAL_MEMO FOR EACH ROW
DECLARE
  DT_TRX     DATE;
  DS_TRX	 VARCHAR2(2000);
  DT_ENT     DATE;
  USR_ENT    VARCHAR2(50);
  V_SEQ_NO   NUMBER;
  V_CEK_JM   NUMBER;
  V_PC_CODE         VARCHAR2(10); 
  V_KP_CODE         VARCHAR2(10);
  V_BAGIAN_CODE     VARCHAR2(10);
  V_SECTION_CODE    VARCHAR2(10);
BEGIN
    SELECT DATE_OF_TRX, DESC_TRX, DATE_OF_ENTRY, USER_ENTRY,SEQ_NO, PC_CODE, KP_CODE, BAGIAN_CODE, SECTION_CODE
	INTO DT_TRX, DS_TRX, DT_ENT, USR_ENT, V_SEQ_NO, V_PC_CODE, V_KP_CODE, V_BAGIAN_CODE, V_SECTION_CODE
	FROM MST_TRX_JOURNAL_MEMO
	WHERE NUM_OF_TRX_JOURNAL_MEMO = :NEW.NUM_OF_TRX_JOURNAL_MEMO;

    INSERT INTO JOURNAL
    (NUM_OF_TRX, DATE_OF_TRX, DESC_OF_TRANS, ACCOUNT,
    VALUE_DB, VALUE_CR, VALUE_INT_DB, VALUE_INT_CR, DATE_OF_ENTRY, USER_ENTRY,
    PC_CODE, KP_CODE, CODE_BAGIAN, SECTION_CODE, SEQ_NO,SLA_CODE,SLA_NAME, CURRENCY_CODE, RATE)
    VALUES
    (:NEW.NUM_OF_TRX_JOURNAL_MEMO, DT_TRX, DECODE(:NEW.DESCRIPTION, NULL, DS_TRX, :NEW.DESCRIPTION), :NEW.ACCOUNT,
    :NEW.VALUE_DB, :NEW.VALUE_CR, :NEW.VALUE_INT_DB, :NEW.VALUE_INT_CR, DT_ENT, USR_ENT,
    V_PC_CODE, V_KP_CODE, V_BAGIAN_CODE, V_SECTION_CODE, V_SEQ_NO, :NEW.SLA_CODE,:NEW.SLA_NAME, :NEW.CURRENCY_CODE, :NEW.RATE);
	
END;
/


DROP TABLE F_OTHERS_INCOME_DTL CASCADE CONSTRAINTS;

CREATE TABLE F_OTHERS_INCOME_DTL
(
  OI_NUM          VARCHAR2(30 BYTE)             NOT NULL,
  OI_IDX          NUMBER(3)                     NOT NULL,
  DOI_CODE        VARCHAR2(10 BYTE)             NOT NULL,
  OI_AMOUNT       NUMBER(15)                    NOT NULL,
  OI_DESCRIPTION  VARCHAR2(250 BYTE),
  OI_AMOUNT_CURR  NUMBER,
  SLA_CODE        VARCHAR2(50 BYTE),
  SLA_NAME        VARCHAR2(250 BYTE),
  OI_QTY          NUMBER,
  OI_TAX          VARCHAR2(10 BYTE),
  OI_TAX_RATE     NUMBER,
  OI_PRICE        NUMBER,
  OI_BEFORE_TAX   NUMBER,
  OI_AFTER_TAX    NUMBER,
  OI_VAT_TYPE     VARCHAR2(10 BYTE),
  OI_TAX_AMOUNT   NUMBER,
  CEK_KODE        VARCHAR2(40 BYTE),
  OI_DISC_AMOUNT  NUMBER,
  OI_DISC_PCT     NUMBER,
  OI_DISC_TYPE    VARCHAR2(20 BYTE)
)
TABLESPACE GIT_ACC_FISKAL
PCTUSED    40
PCTFREE    10
INITRANS   1
MAXTRANS   255
STORAGE    (
            INITIAL          128K
            NEXT             1M
            MINEXTENTS       1
            MAXEXTENTS       UNLIMITED
            PCTINCREASE      0
            FREELISTS        1
            FREELIST GROUPS  1
            BUFFER_POOL      DEFAULT
           )
LOGGING 
NOCOMPRESS 
NOCACHE;

COMMENT ON TABLE F_OTHERS_INCOME_DTL IS 'TABLE TRANSACTION OTHERS INCOME DETAIL';

COMMENT ON COLUMN F_OTHERS_INCOME_DTL.OI_NUM IS 'ORTHERS INCOME NUMBER';

COMMENT ON COLUMN F_OTHERS_INCOME_DTL.OI_IDX IS 'OTHERS INCOMDE INDEX';

COMMENT ON COLUMN F_OTHERS_INCOME_DTL.DOI_CODE IS 'MASTER OTHERS INCOME CODE';

COMMENT ON COLUMN F_OTHERS_INCOME_DTL.OI_AMOUNT IS 'OTHERS INCOME AMOUNT';

COMMENT ON COLUMN F_OTHERS_INCOME_DTL.OI_DESCRIPTION IS 'OTHERS INCOME DESCRIPTION';


